mapper.select:
select p.id, p.title, p.content, p.type, p.is_anonymous, p.like_count, p.create_time, CASE WHEN p.is_anonymous = 1 THEN '匿名用户' ELSE COALESCE(u.nickname, u.username) END AS authorName, CASE WHEN p.is_anonymous = 1 THEN NULL ELSE u.avatar END AS authorAvatar, ((SELECT COUNT(*) FROM comment c WHERE c.post_id = p.id) + (SELECT COUNT(*) FROM comment_reply cr WHERE cr.post_id = p.id AND cr.status = 1)) AS commentCount from post p LEFT JOIN user u ON p.user_id = u.id
p.type = #{type}
ORDER BY p.create_time DESC
